CREATE TABLE listing_search_places (
    name text NOT NULL, county text NOT NULL, latitude double precision NOT NULL, longitude double precision NOT NULL
);

CREATE FUNCTION listing_search_text(text) RETURNS text LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS
$$ SELECT trim(regexp_replace(lower(translate($1,'ÁÉÍÓÚáéíóú','AEIOUaeiou')), '[^a-z0-9]+', ' ', 'g')) $$;

